import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, color, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    CircleGeometry,
    Color,
    Vector3,
  } = THREE;

  const root = new Group();
  root.name = config.id || 'journal-card-2';
  root.userData.handlers = {};

  const ownedGeometries = [];
  const ownedMaterials = [];
  const timelines = [];
  const cleanupCallbacks = [];

  const makeBasicMaterial = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    ownedMaterials.push(material);
    return material;
  };

  const backdropGeometry = new PlaneGeometry(7, 6);
  ownedGeometries.push(backdropGeometry);

  const backdropMaterial = makeBasicMaterial({
    transparent: false,
    depthWrite: false,
  });

  const backdropUv = uv();
  backdropMaterial.colorNode = mix(
    color(0x0b0b10),
    mix(
      color(0x16161d),
      color(0x0b0b10),
      smoothstep(0.35, 0.95, backdropUv.y),
    ),
    smoothstep(0.0, 1.0, backdropUv.y),
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'journal-card-2-backdrop';
  backdrop.position.set(0, 0, -2.5);
  backdrop.renderOrder = -10;
  root.add(backdrop);

  const shadowGeometry = new CircleGeometry(1.85, 64);
  ownedGeometries.push(shadowGeometry);

  const shadowMaterial = makeBasicMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.48,
    depthWrite: false,
  });

  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.name = 'journal-card-2-contact-shadow';
  shadow.scale.set(1.55, 0.34, 1);
  shadow.position.set(0, -1.08, -0.12);
  shadow.renderOrder = -2;
  root.add(shadow);

  const panelGeometry = new PlaneGeometry(3.2, 2.0);
  ownedGeometries.push(panelGeometry);

  const panelMaterial = makeBasicMaterial({
    color: 0x16161d,
    transparent: false,
  });

  const panel = new Mesh(panelGeometry, panelMaterial);
  panel.name = 'journal-card-2-surface';
  panel.position.set(0, 0, 0);
  panel.renderOrder = 0;
  root.add(panel);

  const imageGeometry = new PlaneGeometry(3.2, 2.0);
  ownedGeometries.push(imageGeometry);

  const imageMaterial = makeBasicMaterial({
    color: 0xe8ecf2,
    transparent: true,
    opacity: 0.92,
    depthWrite: true,
  });

  const image = new Mesh(imageGeometry, imageMaterial);
  image.name = 'journal-card-2-grain-sprite';
  image.position.set(0, 0, 0.035);
  image.renderOrder = 1;
  root.add(image);

  image.onBeforeRender = (_renderer, _scene, camera) => {
    if (camera) image.quaternion.copy(camera.quaternion);
  };

  const accentGeometry = new PlaneGeometry(0.08, 1.28);
  ownedGeometries.push(accentGeometry);

  const accentMaterial = makeBasicMaterial({
    color: 0xff2a38,
    transparent: false,
  });

  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.name = 'journal-card-2-signal-accent';
  accent.position.set(-1.48, -0.04, 0.065);
  accent.renderOrder = 2;
  root.add(accent);

  const innerFrameGeometry = new PlaneGeometry(2.92, 1.72);
  ownedGeometries.push(innerFrameGeometry);

  const innerFrameMaterial = makeBasicMaterial({
    color: 0xe8ecf2,
    transparent: true,
    opacity: 0.12,
    depthWrite: false,
  });

  const innerFrame = new Mesh(innerFrameGeometry, innerFrameMaterial);
  innerFrame.name = 'journal-card-2-paper-edge';
  innerFrame.position.set(0, 0, 0.055);
  innerFrame.renderOrder = 3;
  root.add(innerFrame);

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl)
      .then((texture) => {
        if (!texture) return;

        texture.colorSpace = THREE.SRGBColorSpace;
        texture.wrapS = THREE.ClampToEdgeWrapping;
        texture.wrapT = THREE.ClampToEdgeWrapping;
        texture.repeat.set(1, 1);
        texture.offset.set(0, 0);
        imageMaterial.map = texture;
        imageMaterial.needsUpdate = true;

        cleanupCallbacks.push(() => {
          if (typeof texture.dispose === 'function') texture.dispose();
        });
      })
      .catch(() => {});
  }

  root.scale.setScalar(0.985);
  const entrance = gsap.timeline();
  entrance.to(root.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.7,
    ease: 'power3.out',
  });
  timelines.push(entrance);

  root.userData.cleanup = () => {
    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }

    image.onBeforeRender = null;

    for (const callback of cleanupCallbacks) callback();
    for (const material of ownedMaterials) material.dispose();
    for (const geometry of ownedGeometries) geometry.dispose();

    root.clear();
  };

  return root;
}
